903	        /**
904	         Tests if two URLs share an HTTP origin, as defined by scheme, host, and effective port.
905	         See <a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-4.3.1">RFC 9110, Section 4.3.1</a>.
906	         */
907	        static boolean sameOrigin(URL first, URL second) {
908	            int firstPort = first.getPort() != -1 ? first.getPort() : first.getDefaultPort();
909	            int secondPort = second.getPort() != -1 ? second.getPort() : second.getDefaultPort();
910	            return first.getProtocol().equalsIgnoreCase(second.getProtocol())
911	                && first.getHost().equalsIgnoreCase(second.getHost())
912	                && firstPort == secondPort;
913	        }
