1218	        void processResponseHeaders(Map<String, List<String>> resHeaders) {
1219	            for (Map.Entry<String, List<String>> entry : resHeaders.entrySet()) {
1220	                String name = entry.getKey();
1221	                if (name == null)
1222	                    continue; // http/1.1 line
1223	
1224	                List<String> values = entry.getValue();
1225	                for (String value : values) {
