        long skipped = 0;
        try {
            while (skipped < requested) {
                int read = read(skipBuffer, 0, (int) Math.min(requested - skipped, skipBuffer.length));
                if (read == -1) break;
                skipped += read;
            }
            return skipped;
        } finally {
